import{_ as d,o as e,c as t,ag as r}from"./chunks/framework.BaNuf0sO.js";const p=JSON.parse('{"title":"ModalConfirm（配置化确认弹窗 / 抽屉）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/modal/docs/README-ModalConfirm.md","filePath":"docs/core/src/components/modal/docs/README-ModalConfirm.md"}'),a={name:"docs/core/src/components/modal/docs/README-ModalConfirm.md"};function s(c,o,i,n,l,h){return e(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="modalconfirm-配置化确认弹窗-抽屉" tabindex="-1">ModalConfirm（配置化确认弹窗 / 抽屉） <a class="header-anchor" href="#modalconfirm-配置化确认弹窗-抽屉" aria-label="Permalink to &quot;ModalConfirm（配置化确认弹窗 / 抽屉）&quot;">​</a></h1><blockquote><p>确认型弹层原语：modal / drawer 双形态一键切换，确认/取消走 Promise 契约（返回 false 不关、resolve 关）。 范式页：<code>apps/reference/src/pages/modal/confirm/showcase/</code>（双形态 + $attrs 透传实证）</p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>何时用</strong>：操作确认、轻量表单提交、任意「弹窗/抽屉外壳 + 自定义内容」场景</li><li><strong>何时不用</strong>：复杂表单提交用 <code>ModalForm</code>；完整 CRUD 用 <code>ModalDetail</code>；「架子 + 注册表」命令式弹窗体系用 <code>ModalShelf</code> + <code>ModalPorter</code></li><li>关键机制：<code>onClose</code>/<code>onCancel</code>/<code>onConfirm</code> 是 <strong>props 不是 emits</strong>（onXxx props 约定），确认/取消回调返回 <code>Promise&lt;boolean|void&gt;</code> 时——返回 <code>false</code> 不关闭、reject 不关闭、resolve 关闭</li><li><code>inheritAttrs: false</code> + 全量 <code>v-bind $attrs</code> 透传底层 ElDialog/ElDrawer：未声明 EP prop（如 <code>draggable</code> / <code>destroy-on-close</code>）直达底层</li></ul><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><p>常规确认弹窗零配置——默认 modal 形态 + 宽 420 + 自动关窗：</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ModalConfirm</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  v-model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">show</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;操作确认&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on-confirm</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">onConfirm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">     &lt;!--</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 异步</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> →</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 自动</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> loading</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 转圈，resolve</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 关窗</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span></code></pre></div><p><strong>要点</strong>：</p><ul><li><code>show</code> 必传（<code>v-model:show</code>）；关闭路径：点确认/取消/遮罩/ESC/右上角关闭 → 统一收敛到 <code>onClose(status)</code>，<code>status=true</code> 表示因确认关闭</li><li>提交类确认让 <code>onConfirm</code> 返回 Promise 并配 <code>use-loading</code>：等待期按钮自动转圈，reject 不关窗（错误留在原地展示）、resolve 关窗</li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong>默认即够用：modal 居中 + 宽 420 + 确认/取消自动关窗</strong>——绝大多数确认弹窗只传 <code>show</code>/<code>title</code>/<code>onConfirm</code>。</li><li><code>layerType=&quot;drawer&quot;</code>：仅当确认内容需要抽屉形态（侧滑、大尺寸自绘内容）时开；drawer 下 <code>width</code> 语义变为抽屉尺寸（size），<code>direction</code> 控制开合方向（仅 drawer 生效）。</li><li><code>modalReserve</code>：默认 <code>200</code>（弹层可用高 = innerHeight − 200）即够用；仅当弹层内嵌表格/表单需要更高可用视口时调小（联动 TableMain 高度链）。</li><li><code>use-loading</code>：仅当 <code>onConfirm</code> 返回 Promise 时配；同步确认无需。</li><li><code>headerDivider</code>/<code>footerDivider</code>：默认随形态（drawer=true / modal=false）；仅需显式覆盖时传。</li><li><code>#footer</code> 自绘操作区：仅当默认底部按钮不满足（需要自绘布局/额外内容）时用，scoped 提供 <code>{cancelHandler, confirmHandler, loading}</code>。</li><li><strong>完整能力演示</strong>（双形态切换 + 异步确认 + 分割线 + $attrs 透传）：<code>apps/reference/src/pages/modal/confirm/showcase/</code>——能力展示，非推荐默认。</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props-内联-defineprops-无-types-ts" tabindex="-1">Props（内联 defineProps，无 types.ts） <a class="header-anchor" href="#props-内联-defineprops-无-types-ts" aria-label="Permalink to &quot;Props（内联 defineProps，无 types.ts）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>show</code></td><td><code>boolean</code>（必传）</td><td>—</td><td>可见性（v-model:show）</td></tr><tr><td><code>showClose</code></td><td><code>boolean</code></td><td><code>true</code></td><td>右上角关闭按钮</td></tr><tr><td><code>onClose</code></td><td><code>(status?: boolean) =&gt; void</code></td><td>—</td><td>关闭回调，status = 是否因确认关闭</td></tr><tr><td><code>onCancel</code></td><td><code>() =&gt; void | Promise&lt;boolean|void&gt;</code></td><td>—</td><td>取消回调；返回 false 则不关闭</td></tr><tr><td><code>onConfirm</code></td><td><code>() =&gt; void | Promise&lt;boolean|void&gt;</code></td><td>—</td><td>确认回调；返回 false 不关闭、reject 不关闭，resolve 关闭并传 status=true</td></tr><tr><td><code>title</code></td><td><code>string | (() =&gt; VNode|VNode[])</code></td><td>—</td><td>标题</td></tr><tr><td><code>content</code></td><td><code>string | (() =&gt; VNode)</code></td><td>—</td><td>正文</td></tr><tr><td><code>cancelText</code></td><td><code>string | (() =&gt; VNode)</code></td><td><code>&quot;取消&quot;</code></td><td>取消按钮文案</td></tr><tr><td><code>confirmText</code></td><td><code>string | (() =&gt; VNode)</code></td><td><code>&quot;确定&quot;</code></td><td>确认按钮文案</td></tr><tr><td><code>hiddenCancel</code></td><td><code>boolean</code></td><td><code>false</code></td><td>隐藏取消按钮</td></tr><tr><td><code>hiddenFooter</code></td><td><code>boolean</code></td><td><code>false</code></td><td><strong>整块隐藏 footer</strong>（操作区容器一并不渲染）。用于「只要弹层容器、不要确认-取消」的场景（如列表详情范式的详情抽屉）。EP 的 dialog / drawer 都按 footer 插槽存在与否渲染容器，故这里是<strong>真不渲染</strong>；[MUST NOT] 改用「传空 <code>#footer</code> 插槽」绕——那会留一条带 padding 的空条（drawer 实测 56px）</td></tr><tr><td><code>hiddenHeader</code></td><td><code>boolean</code></td><td><code>false</code></td><td><strong>整块隐藏 header</strong>（标题区 + 关闭按钮）。两形态实现不同（EP 使然）：<code>drawer</code> 走 EP 原生 <code>with-header=false</code> → 节点真不渲染；<code>modal</code> 的 <code>el-dialog__header</code> <strong>无条件渲染</strong>，只能由 <code>dc-confirm-modal_hidden-header</code> 类 <code>display:none</code> 兜。⚠️ 隐藏后失去关闭按钮，[MUST] 自备关闭入口（遮罩 / ESC / 自绘）</td></tr><tr><td><code>width</code></td><td><code>number | string</code></td><td><code>420</code></td><td>modal = 弹窗宽度 / drawer = 抽屉尺寸（size）</td></tr><tr><td><code>reverse</code></td><td><code>boolean</code></td><td><code>false</code></td><td>反转按钮位置</td></tr><tr><td><code>closeOnPressEscape</code></td><td><code>boolean</code></td><td><code>true</code></td><td>ESC 关闭</td></tr><tr><td><code>closeOnClickModal</code></td><td><code>boolean</code></td><td><code>true</code></td><td>点击遮罩关闭</td></tr><tr><td><code>useLoading</code></td><td><code>boolean</code></td><td>—</td><td>确认按钮 loading（onConfirm 返回 Promise 时转圈）</td></tr><tr><td><code>type</code></td><td><code>ButtonProps[&quot;type&quot;]</code></td><td><code>&quot;primary&quot;</code></td><td>确认按钮 type</td></tr><tr><td><code>layerType</code></td><td><code>&quot;modal&quot; | &quot;drawer&quot;</code></td><td><code>&quot;modal&quot;</code></td><td>modal = ElDialog 居中弹窗 / drawer = ElDrawer</td></tr><tr><td><code>direction</code></td><td><code>&quot;rtl&quot;|&quot;ltr&quot;|&quot;ttb&quot;|&quot;btt&quot;</code></td><td><code>&quot;rtl&quot;</code></td><td>drawer 方向（仅 drawer 生效）</td></tr><tr><td><code>headerDivider</code></td><td><code>boolean</code></td><td>按形态：drawer=true / modal=false</td><td>header 下分割线</td></tr><tr><td><code>footerDivider</code></td><td><code>boolean</code></td><td>按形态：drawer=true / modal=false</td><td>footer 上分割线</td></tr><tr><td><code>modalReserve</code></td><td><code>number</code></td><td><code>200</code></td><td>modal 形态弹层体可用高视口预留 px（provide SCOPE_VIEWPORT_MAX_HEIGHT = innerHeight − modalReserve）</td></tr></tbody></table><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>语义</th></tr></thead><tbody><tr><td><code>update:show</code></td><td><code>boolean</code></td><td>可见性同步（v-model）</td></tr></tbody></table><p>⚠️ <code>onClose</code>/<code>onCancel</code>/<code>onConfirm</code> 是 props 不是 emits（onXxx props 约定）。</p><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td>默认</td><td>无</td><td>正文（content prop 之外的自绘内容区）</td></tr><tr><td><code>#title</code></td><td>无</td><td>标题</td></tr><tr><td><code>#main-header</code></td><td>无</td><td>头部区域（含标题）</td></tr><tr><td><code>#main-footer</code></td><td>无</td><td>底部区域（含按钮）</td></tr><tr><td><code>#footer</code></td><td><code>{cancelHandler, confirmHandler, loading}</code></td><td>完全自绘操作区</td></tr></tbody></table><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无。<code>inheritAttrs: false</code> + 全量 <code>v-bind $attrs</code> 透传底层 ElDialog/ElDrawer（未声明 EP prop 如 <code>draggable</code>/<code>destroy-on-close</code> 直达）；provide <code>BODY_CONTENT_VIEWPORT_HEIGHT</code>（老 key）+ <code>SCOPE_VIEWPORT_MAX_HEIGHT</code>（新 key）。</p><h2 id="抽屉的-chrome-面貌-v0-32-0" tabindex="-1">抽屉的 chrome 面貌（v0.32.0） <a class="header-anchor" href="#抽屉的-chrome-面貌-v0-32-0" aria-label="Permalink to &quot;抽屉的 chrome 面貌（v0.32.0）&quot;">​</a></h2><p>三段结构的观感由三样东西撑起来，<strong>[MUST] 一起看</strong>：</p><table tabindex="0"><thead><tr><th>项</th><th>取值</th><th>为什么</th></tr></thead><tbody><tr><td><strong>分割线</strong></td><td><code>var(--dc-core-border-color, var(--el-border-color))</code></td><td>走规则 14 的两类来源 ⇒ <strong>切主题 / 切亮暗时跟着变</strong>。此前是<strong>裸 <code>--el-border-color-lighter</code></strong>：主题系的 <code>borderColor</code> 映射到 <code>--el-border-color</code>，它读的是另一个变量 ⇒ 换主题时这条线纹丝不动</td></tr><tr><td><strong>header / footer 面色</strong></td><td><code>var(--dc-core-surface, var(--el-bg-color))</code></td><td>与正文分出层次</td></tr><tr><td><strong>三处 padding</strong></td><td>横向三处同取<strong>外圈档</strong>；纵向正文取<strong>外圈档</strong>、header/footer 取<strong>呼吸档</strong></td><td>接回间距阶梯（原先写死 <code>16/20/12 + 20</code>，改 gap 基数 / 密度档时一律不动）</td></tr></tbody></table><p>🔴 <strong>面色与分割线互为保底，[MUST] 两个都要</strong>：单靠色差在暗色下不够 —— 本仓实测 <code>ground ↔ surface</code> 色差<strong>亮 18 / 暗仅 10</strong>。 🔴 <strong>[MUST NOT] 把分割线改成阴影</strong>：本仓去框化那次的原话「暗色下投影不可见、只剩灰框」。 🔴 <strong>横向三处同值不可拆</strong>：标题 / 正文 / footer 的<strong>左缘恒对齐</strong> —— 让 chrome 取呼吸档而正文取外圈档会差一档，本仓为这条对齐专门返工过。</p><h3 id="🔴-抽屉正文取底色-modal-正文仍是面-v0-32-0" tabindex="-1">🔴 抽屉正文取<strong>底色</strong>，modal 正文仍是<strong>面</strong>（v0.32.0） <a class="header-anchor" href="#🔴-抽屉正文取底色-modal-正文仍是面-v0-32-0" aria-label="Permalink to &quot;🔴 抽屉正文取**底色**，modal 正文仍是**面**（v0.32.0）&quot;">​</a></h3><p>三段层次：<strong>chrome 面 / 正文底 / 正文里的卡再成面</strong>。</p><table tabindex="0"><thead><tr><th>形态</th><th>正文底</th><th>正文里的组件（<code>TableMain</code> / <code>DataGridView</code> / <code>InfiniteListView</code> / <code>FormSubmitPanel</code>）</th></tr></thead><tbody><tr><td><strong>drawer</strong></td><td><strong>底色</strong>（<code>--dc-core-ground</code>）</td><td><strong>自持面</strong>（v0.32.0 起恢复）</td></tr><tr><td><strong>modal</strong></td><td>面（EP 的 overlay 档）</td><td><strong>不二次成面</strong>（逐字不变）</td></tr></tbody></table><p>这靠<strong>两个不同的槽位标</strong>实现：<code>SlotRegion.ModalConfirm_Body</code>（modal）与 <code>SlotRegion.ModalConfirm_DrawerBody</code>（drawer）。 🔴 <strong>[MUST NOT] 合成一个标再反转它的含义</strong> —— 那个标的语义一直是「<strong>你脚下是一块面</strong>」， 抽屉正文改成底之后它就不再是那个意思了；反转含义会把 modal 形态一起改掉， 而 modal 那儿的自动关面是<strong>对的</strong>。</p><p>⚠️ <strong>两档都 provide 有界可用高</strong> ⇒ <code>ViewLayout</code> / <code>TabsMain</code> 的 <code>refine</code> 默认 <strong>两个档都列</strong>，漏一个就是「抽屉里掉回自然流」。</p><p>⚠️ <strong>暗色下单靠色差不够</strong>（<code>ground ↔ surface</code> 实测亮 18 / 暗仅 10）—— 三段层次 [MUST] 与 header/footer 的<strong>分割线一起</strong>看，[MUST NOT] 因为加了底色就撤线。</p><h3 id="下游-既有的显式-surface-false-要撤" tabindex="-1">下游：既有的显式 <code>surface: false</code> 要撤 <a class="header-anchor" href="#下游-既有的显式-surface-false-要撤" aria-label="Permalink to &quot;下游：既有的显式 `surface: false` 要撤&quot;">​</a></h3><p>抽屉 → <code>ListLayout</code> → <code>TableMain</code> 这种<strong>隔了容器</strong>的场景，此前自动关面<strong>够不着</strong> （<code>useContextDefaults</code> 只读直系父 DOM）⇒ 使用方得手动传 <code>surface: false</code> 兜着。 正文改底色后<strong>那份手动补偿反过来了</strong>：现在传 <code>false</code> 会让内容<strong>摊在底色上</strong>。 ⇒ <strong>撤掉它</strong>（撤了就是对的）。</p><h3 id="padding-为什么必须落在-el-drawer-body" tabindex="-1">padding 为什么必须落在 <code>.el-drawer__body</code> <a class="header-anchor" href="#padding-为什么必须落在-el-drawer-body" aria-label="Permalink to &quot;padding 为什么必须落在 `.el-drawer__body`&quot;">​</a></h3><p>被观测的正是 <code>__body</code>（内容可用高 = 它的 <code>contentRect.height</code>，已扣其 padding） ⇒ 改它的 padding，provide 出去的可用高<strong>自动跟上、零 JS 改动</strong>。</p><p>🔴 <strong>[MUST NOT] 挪到 <code>.confirm-modal__content</code>（子元素）</strong>：那份 padding 在被量的盒子 <strong>里面</strong>、不会从可用高里扣 ⇒ 内部 <code>ListLayout</code> / <code>ViewLayout</code> 拿到的可用高多出 2×padding ⇒ <strong>每个抽屉恒溢出</strong>（v0.28 修过的「refine 四类恒定溢出」第三类）。</p><p>ℹ️ 值经 <code>:style</code> 以 CSS 变量挂在弹层元素上，<strong>[MUST NOT] 改用 <code>v-bind()</code></strong> —— 打这些 EP 结构类的样式块是<strong>非 scoped</strong> 的、目标元素被 teleport 到了 body， 而 <code>v-bind()</code> 的变量挂在<strong>组件根</strong>上，够不着。</p><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong>关闭回调命名三件套是 props</strong>：<code>onClose</code>/<code>onCancel</code>/<code>onConfirm</code> 走 props 传（<code>:on-confirm=&quot;...&quot;</code>），不是 <code>@confirm</code>；emit 侧只有 <code>update:show</code></li><li><strong>onConfirm 的 false / reject 语义</strong>：返回 <code>false</code> 不关闭、reject 不关闭（错误留窗内展示）、resolve 关闭——三条路径别写混</li><li><strong><code>closeOnClickModal</code> / <code>closeOnPressEscape</code> 默认开</strong>：误触遮罩/ESC 即关，需要「不可轻易关闭」的强确认场景显式关掉</li><li><strong><code>headerDivider</code> / <code>footerDivider</code> 默认随形态</strong>：drawer=true / modal=false；直接不传会得到形态默认值，别以为「没传就是没有」</li><li><strong><code>direction</code> 只在 drawer 生效</strong>：modal 形态传了不报错也不生效</li><li><strong>老 key 并存</strong>：<code>BODY_CONTENT_VIEWPORT_HEIGHT</code>（老）+ <code>SCOPE_VIEWPORT_MAX_HEIGHT</code>（新）双 provide，消费新 key 即可</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>弹层族：<code>ModalForm</code>（组合 ModalConfirm + FormMain 做表单提交）、<code>ModalDetail</code>（CRUD 预设薄壳，内部委托 ModalForm）</li><li>命令式弹窗体系：<code>ModalShelf</code>（架子 + level 层级）+ <code>ModalPorter</code>（modalList 注册表）</li><li>视口可用高链：<code>modalReserve</code> → provide <code>SCOPE_VIEWPORT_MAX_HEIGHT</code>（新 key）/ <code>BODY_CONTENT_VIEWPORT_HEIGHT</code>（老 key），TableMain <code>viewportHeight</code>/<code>parentChannel</code> 同链消费</li><li>范式页：<code>apps/reference/src/pages/modal/confirm/showcase/</code></li></ul>',42)])])}const m=d(a,[["render",s]]);export{p as __pageData,m as default};
